package net.imadz.codegen.scaffolding.cqrs.template.products

import net.imadz.codegen.scaffolding.cqrs.model.products._
import net.imadz.codegen.structure.NamingConventions

object ProductBuildTemplate {
  def generate(model: ProductDomainModel, externalIngress: Boolean = false): Vector[ProductSourceModel] = {
    val sources = model.aggregates.map(_.declaration.source)
    def entry(path: String, content: String, kind: String): ProductSourceModel = ProductSourceModel(path,
      (if (path.endsWith(".properties") || path.endsWith(".conf")) "" else "// @generated by CodegenMain:semantic-products-1\n") + content, kind, sources, model.footprint)
    val build = """scalaVersion := "2.13.14"

Compile / unmanagedSourceDirectories += baseDirectory.value / "app"
Compile / PB.protoSources := Seq(baseDirectory.value / "app" / "protobuf")
Compile / PB.targets := Seq(scalapb.gen() -> (Compile / sourceManaged).value)
libraryDependencies ++= Seq(
  "com.typesafe.akka" %% "akka-persistence-typed" % "2.6.20",
  "com.typesafe.akka" %% "akka-persistence-testkit" % "2.6.20" % Test,
  "com.typesafe.akka" %% "akka-actor-testkit-typed" % "2.6.20" % Test,
  "com.thesamet.scalapb" %% "scalapb-runtime" % "0.11.14" % "protobuf",
  "org.scalatest" %% "scalatest" % "3.2.15" % Test
)
Test / parallelExecution := false
"""
    val plugins = """addSbtPlugin("com.thesamet" % "sbt-protoc" % "1.0.6")
libraryDependencies += "com.thesamet.scalapb" %% "compilerplugin" % "0.11.14"
"""
    val exactTests = model.exact.map { d =>
      val pkg = model.packages(d.domain.context); val name = pkg + ".domain.values." + NamingConventions.productSymbol(d.domain.id)
      val amount = if (d.scale == 0) "1" else "0." + ("0" * (d.scale - 1)) + "1"
      val value = name + "(BigDecimal(" + ujson.write(amount) + ")" + d.unitMember.map(_ => ", " + ujson.write(d.units.head)).getOrElse("") + ")"
      "  test(" + ujson.write(d.domain.context + "/" + d.domain.id + " exact domain wire PO and protobuf roundtrip") + ") {\n" +
        "    val value = " + value + "\n    val c = " + pkg + ".infrastructure.serialization.DomainConverters\n" +
        "    assert(c." + NamingConventions.productSymbol(d.domain.id + "FromWire") + "(c." + NamingConventions.productSymbol(d.domain.id + "ToWire") + "(value)) == value)\n" +
        "    assert(c." + NamingConventions.productSymbol(d.domain.id + "FromPO") + "(c." + NamingConventions.productSymbol(d.domain.id + "ToPO") + "(value)) == value)\n" +
        "    val encoded = c.encode" + d.domain.id + "PB(value)\n" +
        "    assert(c.decode" + d.domain.id + "PB(" + pkg + ".infrastructure.proto." + d.domain.id + "PB.parseFrom(encoded.toByteArray)) == value)\n" +
        "    intercept[IllegalArgumentException](c.decode" + d.domain.id + "PB(encoded.copy(f0 = \"1e2\")))\n  }\n"
    }.mkString
    val spec = "import org.scalatest.funsuite.AnyFunSuite\n\nfinal class GeneratedDomainRoundtripSpec extends AnyFunSuite {\n" + model.aggregates.map { a =>
      val pkg = model.packages(a.declaration.ref.context); val name = NamingConventions.productSymbol(a.declaration.ref.id)
      "  test(" + ujson.write(a.declaration.ref.context + "/" + a.declaration.ref.id + " state survives actual protobuf bytes") + ") {\n" +
        "    val state = " + pkg + ".domain." + name + "State.empty\n    val encoded = " + pkg + ".infrastructure.serialization.DomainConverters.encode" + a.declaration.ref.id + "StatePB(state)\n" +
        "    val parsed = " + pkg + ".infrastructure.proto." + a.declaration.ref.id + "StatePB.parseFrom(encoded.toByteArray)\n" +
        "    assert(" + pkg + ".infrastructure.serialization.DomainConverters.decode" + a.declaration.ref.id + "StatePB(parsed) == state)\n  }\n"
    }.mkString + exactTests + "}\n"
    val actorSpec = "import akka.actor.testkit.typed.scaladsl.ActorTestKit\nimport akka.persistence.testkit.PersistenceTestKitPlugin\nimport com.typesafe.config.ConfigFactory\nimport org.scalatest.funsuite.AnyFunSuite\n\nfinal class GeneratedActorStateSpec extends AnyFunSuite {\n" + model.aggregates.map { a =>
      val pkg = model.packages(a.declaration.ref.context); val name = NamingConventions.productSymbol(a.declaration.ref.id)
      val authority = if (externalIngress && a.external.nonEmpty) ", new " + pkg + ".domain." + name + "Aggregate.ExternalAuthority { def authorize(producer: String, authorization: String, identity: Vector[String]): Boolean = false }" else ""
      val methods = a.hosts.map(h => "        def " + NamingConventions.productSymbol(h.id.id) + "(state: " + pkg + ".domain." + name + "State, p: " + pkg + ".domain." + name + "Protocol." + NamingConventions.productSymbol(h.command.id) + ") = throw new UnsupportedOperationException(\"query-only test port\")\n").mkString
      "  test(" + ujson.write(a.declaration.ref.context + "/" + a.declaration.ref.id + " real actor serves typed state") + ") {\n" +
        "    val kit = ActorTestKit(ConfigFactory.parseString(\"akka.actor.provider = local\").withFallback(PersistenceTestKitPlugin.config).withFallback(ConfigFactory.load()))\n" +
        "    try {\n      val hosts = new " + pkg + ".domain." + name + "Computations {\n" + methods + "      }\n" +
        "      val ref = kit.spawn(" + pkg + ".domain." + name + "AggregateFactory.create(\"generated-" + a.declaration.ref.id + "\", " + pkg + ".domain." + name + "State.empty, hosts" + authority + "))\n" +
        "      val probe = kit.createTestProbe[" + pkg + ".domain." + name + "State]()\n      ref ! " + pkg + ".domain." + name + "Aggregate.GetState(probe.ref)\n" +
        "      probe.expectMessage(" + pkg + ".domain." + name + "State.empty)\n    } finally kit.shutdownTestKit()\n  }\n"
    }.mkString + ProductVerificationTemplate.tests(model) + "}\n"
    val application = "akka.actor.allow-java-serialization = off\nakka.actor.warn-about-java-serializer-usage = on\nakka.actor.serializers {\n" + model.layout.contexts.zipWithIndex.map { case (c, i) =>
      "  domainProto" + i + " = " + ujson.write(model.packages(c) + ".infrastructure.serialization.DomainProtoSerializer") + "\n"
    }.mkString + "}\nakka.actor.serialization-bindings {\n" + model.wire.map(n => "  " + ujson.write(n.packageName + ".infrastructure.proto." + n.name) + " = domainProto" + model.layout.contexts.indexWhere(c => model.packages(c) == n.packageName) + "\n").mkString + "}\n"
    Vector(entry("build.sbt", build, "build"), entry("project/plugins.sbt", plugins, "build"),
      entry("src/main/resources/application.conf", application, "build"),
      entry("project/build.properties", "sbt.version=1.11.7\n", "build"), entry("src/test/scala/GeneratedDomainRoundtripSpec.scala", spec, "generated-test"),
      entry("src/test/scala/GeneratedActorStateSpec.scala", actorSpec, "generated-test"))
  }
}
